1  reorder_marks_arabic (const hb_ot_shape_plan_t *plan,
     2                        hb_buffer_t              *buffer,
     3                        unsigned int              start,
     4                        unsigned int              end)
     5  {
     6    hb_glyph_info_t *info = buffer->info;
     7
     8    unsigned int i = start;
     9    for (unsigned int cc = 220; cc <= 230; cc += 10)
    10    {
    11      DEBUG_MSG (ARABIC, buffer, "Looking for %d's starting at %d\n", cc, i);
    12      while (i < end && info_cc(info[i]) < cc)
    13        i++;
    14      DEBUG_MSG (ARABIC, buffer, "Looking for %d's stopped at %d\n", cc, i);
    15
    16      if (i == end)
    17        break;
    18
    19      if (info_cc(info[i]) > cc)
    20        continue;
    21
    22      /* Technically we should also check "info_cc(info[j]) == cc"
    23       * in the following loop.  But not doing it is safe; we might
    24       * end up moving all the 220 MCMs and 230 MCMs together in one
    25       * move and be done. */
    26      unsigned int j = i;
    27      while (j < end && info_is_mcm (info[j]))
    28        j++;
    29      DEBUG_MSG (ARABIC, buffer, "Found %d's from %d to %d\n", cc, i, j);
    30
    31      if (i == j)
    32        continue;
    33
    34      /* Shift it! */
    35      DEBUG_MSG (ARABIC, buffer, "Shifting %d's: %d %d\n", cc, i, j);
    36      hb_glyph_info_t temp[HB_OT_SHAPE_COMPLEX_MAX_COMBINING_MARKS];
    37      assert (j - i <= ARRAY_LENGTH (temp));
    38      buffer->merge_out_clusters (start, j);
    39      memmove (temp, &info[i], (j - i) * sizeof (hb_glyph_info_t));
    40      memmove (&info[start + j - i], &info[start], (i - start) * sizeof (hb_glyph_info_t));
    41      memmove (&info[start], temp, (j - i) * sizeof (hb_glyph_info_t));
